'use strict';
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={'Salade':'Salades','Entrees':'Entrées & à partager','Accompagnement':'Accompagnements','Plat principal':'Les plats','Burger':'Burgers','Pates':'Les pâtes','Bucket Meals':'Poulet croustillant','Sandwich':'Sandwichs','Asian (Wok Boule)':'Les woks','Desserts et Crepes':'Desserts & crêpes','Bier':'Bières','Petit Dejeuner':'Petit-déjeuner','Les Oeufs':'Les œufs','Les Vennoiseries':'Viennoiseries','Gauffres & Pancakes':'Gaufres & pancakes','Nos Formule':'Les formules','Platters Celia':'Les plateaux','Maki Rolls (8 Pcs)':'Maki rolls · 8 pièces'};
const configs={cuisine:['LA TABLE CÉLIA','L’art de<br><em>bien manger.</em>','original-2367.webp'],sushi:['SUSHI TERRACE','Le goût<br><em>du voyage.</em>','original-2369.webp'],bar:['LE LOUNGE BAR','Prolongez<br><em>l’instant.</em>','original-2359.webp'],breakfast:['LES MATINS CÉLIA','Un réveil<br><em>tout en douceur.</em>','terrasse.jpeg']};
const art={'Salade':['original-2348.webp','salad.webp'],'Entrees':['original-2356.webp','original-2362.webp'],'Accompagnement':['original-2364.webp','fish.webp'],'Plat principal':['original-2367.webp','original-2368.webp'],'Burger':['burger.webp','original-2350.webp'],'Pizza':['pizza.webp','original-2354.webp'],'Pates':['original-2353.webp','pasta.webp'],'Bucket Meals':['crispy.webp','original-2361.webp'],'Sandwich':['sandwich.webp','original-2358.webp'],'Asian (Wok Boule)':['wok.webp','original-2364.webp'],'Desserts et Crepes':['dessert.webp','dessert.webp']};
let worlds;let motion=!matchMedia('(prefers-reduced-motion: reduce)').matches;
function item(i){return `<article class="menu-item"><div class="item-row"><h4>${esc(i.name.replace(/Celia/g,'Célia'))}</h4><span class="item-price">${esc(i.price)}</span></div>${i.description?`<p class="item-desc">${esc(i.description)}</p>`:''}</article>`}
function jump(w,category){const target=category?document.getElementById('category-'+w+'-'+worlds[w].findIndex(c=>c.category===category)):$(w);target?.scrollIntoView({behavior:motion?'smooth':'instant',block:'start'})}
function renderAll(){let index=0;$('all-menus').innerHTML=Object.entries(worlds).map(([w,cats])=>{const cfg=configs[w];return `<section id="${w}" class="world-section"><div class="world-heading"><p class="eyebrow">${String(Object.keys(worlds).indexOf(w)+1).padStart(2,'0')} / ${cfg[0]}</p><h2>${w==='cuisine'?'La cuisine':w==='sushi'?'Sushi Terrace':w==='bar'?'Le lounge bar':'Le petit-déjeuner'}</h2><p>${cats.reduce((n,c)=>n+c.items.length,0)} références · Faites défiler pour tout découvrir</p></div>${cats.map((c,i)=>{const pair=art[c.category]||[cfg[2],w==='sushi'?'sushi.webp':w==='bar'?'drinks.webp':'terrasse.jpeg'];const style=index++%3===1?'cinematic':index%3===0?'reversed':'editorial';return `<section id="category-${w}-${i}" class="spread scroll-spread ${style}" aria-label="${esc(names[c.category]||c.category)}"><div class="photo-page"><img src="assets/${pair[0]}" alt="Visuel Célia — ${esc(names[c.category]||c.category)}" loading="lazy"><span class="vertical">${cfg[0]}</span><div class="photo-copy"><p>${cfg[0]}</p><h3>${cfg[1]}</h3></div></div><div class="paper-page"><div class="page-top"><span>CÉLIA TERRASSE</span><span>${c.items.length} SAVEURS</span></div><h3>${esc(names[c.category]||c.category)}</h3><div>${c.items.map(item).join('')}</div><div class="page-footer"><span>PRIX EN DOLLARS US</span><a href="#${w}">Début de la section ↑</a></div></div></section>`}).join('')}</section>`}).join('');const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){document.querySelectorAll('[data-section]').forEach(a=>{const active=a.dataset.section===e.target.id;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}})},{rootMargin:'-15% 0px -65% 0px',threshold:0});document.querySelectorAll('.world-section').forEach(s=>observer.observe(s));}
function catalog(){const q=$('search').value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();let count=0;const html=[];Object.entries(worlds).forEach(([w,cats])=>cats.forEach(c=>{const found=c.items.filter(i=>[i.name,i.description,c.category,names[c.category]||''].join(' ').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(q));count+=found.length;if(found.length)html.push(`<section class="catalog-group"><button data-jump="${w}" data-category="${esc(c.category)}">${esc(names[c.category]||c.category)} <span>${configs[w][0]} ↗</span></button><div class="catalog-items">${found.map(item).join('')}</div></section>`)}));$('result-count').textContent=`${count} références ${q?'trouvées':'dans la carte complète'}`;$('catalog-content').innerHTML=html.join('')||'<p>Aucun résultat. Essayez un autre mot.</p>';$('catalog-content').querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{$('catalog').close();jump(b.dataset.jump,b.dataset.category)});}
function openCatalog(){if(!worlds)return;catalog();$('catalog').showModal();$('search').focus()}
function updateMotion(){document.body.classList.toggle('motion-off',!motion);$('motion').textContent=`Mouvement : ${motion?'activé':'en pause'}`;$('motion').setAttribute('aria-pressed',motion)}
$('motion').onclick=()=>{motion=!motion;updateMotion()};updateMotion();
document.querySelectorAll('[data-world]').forEach(b=>b.onclick=()=>{if(worlds)jump(b.dataset.world)});
$('open-index').onclick=openCatalog;$('index-button').onclick=openCatalog;$('close-index').onclick=()=>$('catalog').close();$('search').oninput=catalog;$('close-photo').onclick=()=>$('lightbox').close();
const captions={2347:'Escalope et tagliatelles',2348:'Salade grecque',2349:'Sushi — saumon et avocat',2350:'Viande grillée',2351:'Pâtes à la bolognaise',2352:'Saumon et sauce crémeuse',2353:'Pâtes, simplement irrésistibles',2354:'Pizza pepperoni',2355:'Crevettes grillées et frites',2356:'Salade aux agrumes',2357:'Saveurs marines',2358:'Sandwich grillé',2359:'Cocktails Célia',2360:'L’essence de vos soirées',2361:'Poulet croustillant',2362:'Fraîcheur et salade',2363:'Poisson grillé',2364:'Légumes et touche du chef',2365:'La table Célia',2366:'Poisson entier au citron',2367:'Steak, frites et légumes',2368:'Poisson, légumes et pommes de terre',2369:'Les plateaux sushi'};
$('gallery-track').innerHTML=Object.entries(captions).map(([n,label])=>`<button data-photo="original-${n}.webp" data-caption="${esc(label)}" aria-label="Agrandir : ${esc(label)}"><img src="assets/original-${n}.webp" alt="${esc(label)}" loading="lazy" width="1320" height="1650"><span aria-hidden="true">＋</span></button>`).join('');$('gallery-track').insertAdjacentHTML('beforeend',['fish','sushi','drinks','crispy','burger','dessert','pizza','salad','pasta','wok','sandwich'].map(n=>`<button data-photo="${n}.webp" data-caption="Visuel recréé — ${n}" aria-label="Agrandir le visuel recréé ${n}"><img src="assets/${n}.webp" alt="Visuel culinaire recréé — ${n}" loading="lazy" width="1536" height="1024"><span aria-hidden="true">＋</span></button>`).join(''));$('gallery-track').querySelectorAll('button').forEach(b=>b.onclick=()=>{$('large-photo').src=`assets/${b.dataset.photo}`;$('large-photo').alt=b.dataset.caption;$('photo-caption').textContent=b.dataset.caption;$('lightbox').showModal()});
fetch('menu.json').then(r=>{if(!r.ok)throw Error('Carte indisponible');return r.json()}).then(data=>{worlds={cuisine:data.lounge.slice(0,11),sushi:data.sushi,bar:data.lounge.slice(11),breakfast:data.breakfast};renderAll();}).catch(e=>{$('all-menus').innerHTML='<p>La carte ne peut pas être chargée. <a href="carte-celia.pdf">Ouvrir le PDF</a></p>';console.error(e)});
